def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str) -> list[str]:
        tokens: list[str] = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
            elif c in "+-*/(),:":
                tokens.append(c)
                i += 1
            elif c == "<":
                if i + 1 < n and s[i + 1] in ("=", ">"):
                    tokens.append(s[i : i + 2])
                    i += 2
                else:
                    tokens.append(c)
                    i += 1
            elif c == ">":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(">=")
                    i += 2
                else:
                    tokens.append(c)
                    i += 1
            elif c == "=":
                tokens.append("=")
                i += 1
            elif c.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:
                j = i + 1
                while j < n and s[j].isalnum():
                    j += 1
                tokens.append(s[i:j])
                i = j
        return tokens

    def parse(tokens: list[str]) -> tuple:
        pos = 0
        n = len(tokens)

        def parse_expr() -> tuple:
            nonlocal pos
            left = parse_term()
            while pos < n and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                right = parse_term()
                left = ("binop", op, left, right)
            return left

        def parse_term() -> tuple:
            nonlocal pos
            left = parse_unary()
            while pos < n and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                right = parse_unary()
                left = ("binop", op, left, right)
            return left

        def parse_unary() -> tuple:
            nonlocal pos
            if tokens[pos] == "-":
                pos += 1
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom() -> tuple:
            nonlocal pos
            tok = tokens[pos]
            if tok[0].isdigit():
                pos += 1
                return ("num", int(tok))
            if tok == "(":
                pos += 1
                expr = parse_expr()
                pos += 1  # ')'
                return expr
            if tok in ("SUM", "MIN", "MAX"):
                func = tok
                pos += 2  # func, '('
                args = []
                while True:
                    if pos + 1 < n and tokens[pos + 1] == ":":
                        c1 = tokens[pos]
                        c2 = tokens[pos + 2]
                        pos += 3
                        args.append(("range", c1, c2))
                    else:
                        args.append(("expr", parse_expr()))
                    if tokens[pos] == ",":
                        pos += 1
                    else:
                        pos += 1  # ')'
                        break
                return ("agg", func, args)
            if tok == "IF":
                pos += 2  # 'IF', '('
                left = parse_expr()
                cmp_op = tokens[pos]
                pos += 1
                right = parse_expr()
                pos += 1  # ','
                then_b = parse_expr()
                pos += 1  # ','
                else_b = parse_expr()
                pos += 1  # ')'
                return ("if", cmp_op, left, right, then_b, else_b)
            pos += 1
            return ("cell", tok)

        return parse_expr()

    result: dict[str, int | str] = {}
    asts: dict[str, tuple] = {}
    for name, content in cells.items():
        if content.startswith("="):
            asts[name] = parse(tokenize(content[1:]))
        else:
            result[name] = int(content)

    visiting: set[str] = set()

    for start_name in cells:
        if start_name in result:
            continue
        vstack: list[int | str] = []
        wstack: list[tuple] = [("cell", start_name)]

        while wstack:
            frame = wstack.pop()
            tag = frame[0]

            if tag == "cell":
                cname = frame[1]
                if cname not in cells:
                    vstack.append(0)
                elif cname in result:
                    vstack.append(result[cname])
                elif cname in visiting:
                    vstack.append("#CYCLE!")
                else:
                    visiting.add(cname)
                    wstack.append(("finish_cell", cname))
                    wstack.append(("node", asts[cname]))

            elif tag == "finish_cell":
                cname = frame[1]
                visiting.remove(cname)
                result[cname] = vstack[-1]

            elif tag == "node":
                node = frame[1]
                kind = node[0]
                if kind == "num":
                    vstack.append(node[1])
                elif kind == "cell":
                    wstack.append(("cell", node[1]))
                elif kind == "neg":
                    wstack.append(("neg_apply",))
                    wstack.append(("node", node[1]))
                elif kind == "binop":
                    _, op, left, right = node
                    wstack.append(("binop_left", op, right))
                    wstack.append(("node", left))
                elif kind == "if":
                    _, cmp_op, left, right, then_b, else_b = node
                    wstack.append(("if_left", cmp_op, right, then_b, else_b))
                    wstack.append(("node", left))
                else:  # "agg"
                    _, func, args = node
                    items: list[tuple] = []
                    for arg in args:
                        if arg[0] == "range":
                            _, c1, c2 = arg
                            col1, row1 = ord(c1[0]), int(c1[1:])
                            col2, row2 = ord(c2[0]), int(c2[1:])
                            c_lo, c_hi = (col1, col2) if col1 <= col2 else (col2, col1)
                            r_lo, r_hi = (row1, row2) if row1 <= row2 else (row2, row1)
                            for r in range(r_lo, r_hi + 1):
                                for c in range(c_lo, c_hi + 1):
                                    rc = f"{chr(c)}{r}"
                                    if rc in cells:
                                        items.append(("cell", rc))
                        else:
                            items.append(arg[1])
                    if not items:
                        vstack.append(0)
                    else:
                        wstack.append(("agg_step", func, items, 0, False, 0))

            elif tag == "neg_apply":
                v = vstack.pop()
                vstack.append(v if isinstance(v, str) else -v)

            elif tag == "binop_left":
                _, op, right = frame
                if not isinstance(vstack[-1], str):
                    wstack.append(("binop_right", op))
                    wstack.append(("node", right))

            elif tag == "binop_right":
                op = frame[1]
                r_val = vstack.pop()
                l_val = vstack.pop()
                if isinstance(r_val, str):
                    vstack.append(r_val)
                elif op == "+":
                    vstack.append(l_val + r_val)
                elif op == "-":
                    vstack.append(l_val - r_val)
                elif op == "*":
                    vstack.append(l_val * r_val)
                else:
                    if r_val == 0:
                        vstack.append("#DIV/0!")
                    else:
                        q = abs(l_val) // abs(r_val)
                        vstack.append(-q if (l_val < 0) ^ (r_val < 0) else q)

            elif tag == "if_left":
                _, cmp_op, right, then_b, else_b = frame
                if not isinstance(vstack[-1], str):
                    wstack.append(("if_right", cmp_op, then_b, else_b))
                    wstack.append(("node", right))

            elif tag == "if_right":
                _, cmp_op, then_b, else_b = frame
                r_val = vstack.pop()
                l_val = vstack.pop()
                if isinstance(r_val, str):
                    vstack.append(r_val)
                else:
                    if cmp_op == "=":
                        cond = l_val == r_val
                    elif cmp_op == "<>":
                        cond = l_val != r_val
                    elif cmp_op == "<":
                        cond = l_val < r_val
                    elif cmp_op == "<=":
                        cond = l_val <= r_val
                    elif cmp_op == ">":
                        cond = l_val > r_val
                    else:
                        cond = l_val >= r_val
                    wstack.append(("node", then_b if cond else else_b))

            else:  # "agg_step"
                _, func, items, idx, has_val, acc = frame
                if idx > 0:
                    v = vstack.pop()
                    if isinstance(v, str):
                        vstack.append(v)
                        continue
                    if not has_val:
                        acc = v
                        has_val = True
                    elif func == "SUM":
                        acc += v
                    elif func == "MIN":
                        if v < acc:
                            acc = v
                    else:
                        if v > acc:
                            acc = v
                if idx == len(items):
                    vstack.append(acc if has_val else 0)
                else:
                    wstack.append(("agg_step", func, items, idx + 1, has_val, acc))
                    wstack.append(("node", items[idx]))

    return result
